theorem Filter.Tendsto.liminf_le_liminf_comp.{u_6, u_7, u_8} {ι : Type u_6} {α : Type u_7} {β : Type u_8}
  [ConditionallyCompleteLattice β] {v : ι → α} {u : α → β} {f : Filter ι} {g : Filter α}
  (hv : Filter.Tendsto v f g)
  (hvf : Filter.IsCoboundedUnder (fun x1 x2 => x1 ≥ x2) (Filter.map v f) u := by isBoundedDefault)
  (hg : Filter.IsBoundedUnder (fun x1 x2 => x1 ≥ x2) g u := by isBoundedDefault) :
  Filter.liminf u g ≤ Filter.liminf (u ∘ v) f

theorem Filter.liminf_le_liminf_of_le.{u_6, u_7} {α : Type u_6} {β : Type u_7}
  [ConditionallyCompleteLattice β] {f g : Filter α} (h : g ≤ f) {u : α → β}
  (hf : Filter.IsBoundedUnder (fun x1 x2 => x1 ≥ x2) f u := by isBoundedDefault)
  (hg : Filter.IsCoboundedUnder (fun x1 x2 => x1 ≥ x2) g u := by isBoundedDefault) :
  Filter.liminf u f ≤ Filter.liminf u g

theorem Filter.mono_bliminf.{u_1, u_2} {α : Type u_1} {β : Type u_2} [CompleteLattice α] {f : Filter β}
  {p : β → Prop} {u v : β → α} (h : ∀ (x : β), p x → u x ≤ v x) :
  Filter.bliminf u f p ≤ Filter.bliminf v f p

theorem Filter.blimsup_eq.{u_1, u_2} {α : Type u_1} {β : Type u_2} [ConditionallyCompleteLattice α]
  {f : Filter β} {u : β → α} {p : β → Prop} :
  Filter.blimsup u f p = sInf {a | ∀ᶠ (x : β) in f, p x → u x ≤ a}

theorem Filter.le_limsup_of_frequently_le.{u_1, u_4} {α : Type u_1} {ι : Type u_4}
  [ConditionallyCompleteLattice α] {f : Filter ι} {u : ι → α} {a : α}
  (hu : ∃ᶠ (i : ι) in f, a ≤ u i)
  (hu_le : Filter.IsBoundedUnder (fun x1 x2 => x1 ≤ x2) f u := by isBoundedDefault) :
  a ≤ Filter.limsup u f

theorem Filter.liminf_le_of_frequently_le.{u_1, u_4} {α : Type u_1} {ι : Type u_4}
  [ConditionallyCompleteLattice α] {f : Filter ι} {u : ι → α} {a : α}
  (hu : ∃ᶠ (i : ι) in f, u i ≤ a)
  (hu_le : Filter.IsBoundedUnder (fun x1 x2 => x1 ≥ x2) f u := by isBoundedDefault) :
  Filter.liminf u f ≤ a

theorem Filter.limsup_comp.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  [ConditionallyCompleteLattice α] (u : β → α) (v : γ → β) (f : Filter γ) :
  Filter.limsup (u ∘ v) f = Filter.limsup u (Filter.map v f)

theorem Filter.frequently_lt_of_lt_limsup.{u_1, u_2} {α : Type u_1} {β : Type u_2}
  [ConditionallyCompleteLinearOrder β] {f : Filter α} {u : α → β} {b : β}
  (hu : Filter.IsCoboundedUnder (fun x1 x2 => x1 ≤ x2) f u := by isBoundedDefault)
  (h : b < Filter.limsup u f) : ∃ᶠ (x : α) in f, b < u x

