theorem Filter.Tendsto.curry.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {f : α → β → γ}
  {la : Filter α} {lb : Filter β} {lc : Filter γ}
  (h : ∀ᶠ (a : α) in la, Filter.Tendsto (fun b => f a b) lb lc) :
  Filter.Tendsto (↿f) (la.curry lb) lc

theorem Filter.frequently_curry_prod_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {l : Filter α}
  {m : Filter β} {s : Set α} {t : Set β} :
  (∃ᶠ (x : α × β) in l.curry m, x ∈ s ×ˢ t) ↔ (∃ᶠ (x : α) in l, x ∈ s) ∧ ∃ᶠ (y : β) in m, y ∈ t

theorem Filter.frequently_curry_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {l : Filter α} {m : Filter β}
  (p : α × β → Prop) :
  (∃ᶠ (x : α × β) in l.curry m, p x) ↔ ∃ᶠ (x : α) in l, ∃ᶠ (y : β) in m, p (x, y)

theorem Filter.eventually_curry_prod_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {l : Filter α}
  {m : Filter β} {s : Set α} {t : Set β} [l.NeBot] [m.NeBot] :
  (∀ᶠ (x : α × β) in l.curry m, x ∈ s ×ˢ t) ↔ s ∈ l ∧ t ∈ m

theorem Filter.eventually_curry_iff.{u_1, u_2} {α : Type u_1} {β : Type u_2} {l : Filter α} {m : Filter β}
  {p : α × β → Prop} :
  (∀ᶠ (x : α × β) in l.curry m, p x) ↔ ∀ᶠ (x : α) in l, ∀ᶠ (y : β) in m, p (x, y)

